    {"claim": "Tiering decides the moment a record gets created; it says nothing about who controls what that record contains by the time a plaintiff arrives.", "targets": ["AN-8"]},
    {"claim": "You cannot attach liability to a log the liable party has been quietly gutting for three years.", "targets": ["AN-10", "AN-11"]},
    {"claim": "FTC v. Rite Aid did not get reached by a record; it got reached by the Federal Trade Commission's enforcement muscle.", "targets": ["AN-12", "AN-9"]},
    {"claim": "Subject-keying changes whose name is on the record; it does not change who can afford to read it.", "targets": ["AN-9"]},
    {"claim": "The log documents the injury; it never names the defendant.", "targets": ["AN-9", "AN-10"]}
  ]
}

